const F8_SCALE={fr:["Jamais","Parfois","Souvent","Toujours ou presque"],en:["Never","Sometimes","Often","Always or almost"],sw:["Kamwe","Wakati mwingine","Mara nyingi","Kila mara au karibu kila mara"],am:["በፍጹም","አንዳንድ ጊዜ","ብዙ ጊዜ","ሁልጊዜ ወይም ሁልጊዜ ማለት ይቻላል"]};

const F8_DOM={life:["f1","f2","fA","fB"],cope:["f3","f4","f5"],self:["f6"],emb:["f7","f8"]};
const F8_MIN={life:2,cope:2,self:1,emb:1};
const F8_ALL=["f1","f2","f3","f4","f5","f6","f7","f8","fA","fB"];
/* AFYA-FIQ8_calcul_score: value = 4 - answer (FIQL scale, 4 = best QoL); domain = mean of answered items, computed if
   at least F8_MIN answers; NA and blank are missing, never 0; FIQL-equivalent total = sum of the 4 domains (4 to 16),
   only if all 4 are computed; score 0-100 = (total/4 - 1)/3*100; raw AFYA 0-30 = sum of the 10 answers, only if all 10 answered */
function fiq8Scores(a){a=a||{};const val=id=>typeof a[id]==="number"?a[id]:null;
 const out={n:F8_ALL.filter(id=>val(id)!=null).length,na:F8_ALL.filter(id=>a[id]==="na").length};
 for(const k in F8_DOM){const v=F8_DOM[k].map(val).filter(x=>x!=null);out[k]=v.length>=F8_MIN[k]?4-v.reduce((x,y)=>x+y,0)/v.length:null}
 const ks=["life","cope","self","emb"];out.total=ks.every(k=>out[k]!=null)?ks.reduce((x,k)=>x+out[k],0):null;
 out.score100=out.total==null?null:(out.total/4-1)/3*100;
 out.raw=out.n===10?F8_ALL.reduce((x,id)=>x+val(id),0):null;return out}
const f8Total=a=>fiq8Scores(a).total;
const f8n=a=>a?F8_ALL.filter(id=>a[id]!=null).length:0;
const f2=v=>v==null?"n/a":v.toFixed(2);
const wxTotal=w=>w&&w.length===5&&w.every(v=>typeof v==="number")?w.reduce((a,b)=>a+b,0):null;
const wxS=w=>{const v=wxTotal(w);return v==null?"n/a":v};

