/* glass icons of the AFYA FIQ8 answer scale: 0 empty, 1 a little, 2 half, 3 full */
function glass(l,h=30){const w=Math.round(h*.72);const f=[0,.16,.5,1][l]||0;const top=3,bot=h-2,lt=2,rt=w-2,lb=w*.2,rb=w*.8;const fy=bot-(bot-top-2)*f;
 const xAt=y=>{const k=(y-top)/(bot-top);return[lt+(lb-lt)*k,rt+(rb-rt)*k]};const[a1,b1]=xAt(fy);
 return`<svg class="glass" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" aria-hidden="true">${f>0?`<path d="M${a1},${fy} L${b1},${fy} L${rb},${bot} L${lb},${bot} Z" fill="#7fb2dc"/>`:""}<path d="M${lt},${top} L${lb},${bot} L${rb},${bot} L${rt},${top}" fill="none" stroke="#194a6f" stroke-width="2" stroke-linejoin="round"/></svg>`}
