function f8ScaleCard(){return`<div class="f8scale" role="img" aria-label="${esc(t("scaleTitle"))}">${[0,1,2,3].map(n=>`<div><div class="n">${n}</div>${glass(n,46)}<div class="face">${F8_FACE[n]}</div><b>${L(F8_SCALE)[n]}</b><div class="small muted">${t("g"+n)}</div></div>`).join("")}</div>`}const DIFFS=["expo","edges","scar","bleed","time","mat","help","other"];
const COMPS=["inf","dehis","bleed","rvf","fail","other"];const GRADES=["I","II","IIIa","IIIb","IV","V"];
