function rng(seed){let s=seed;return()=>{s=(s*1664525+1013904223)%4294967296;return s/4294967296}}
function genVisit(r,level,seen){
 const wx=[0,0,0,0,0].map((_,i)=>Math.max(0,Math.min(4,Math.round(level*4.1+(r()-.5)*1.6-(i===2?-.3:0)))));
 const active=r()>level*.6;
 const f8={};F8_ITEMS.forEach(it=>{f8[it.id]=Math.max(0,Math.min(3,Math.round(level*3.1+(r()-.5)*1.3)))});f8.fA=Math.max(0,Math.min(3,Math.round(level*2.6+(r()-.5)*1.3)));f8.fB=r()<.15?"na":Math.max(0,Math.min(3,Math.round(level*2.8+(r()-.5)*1.3)));f8.glob=Math.max(0,Math.min(10,Math.round(level*10+(r()-.5)*2)));
 return{wexner:wx,fiq8:f8,sex:{active,reason:active?null:(level>.5?"inc":(r()>.5?"part":"choice")),dysp:r()<level*.5?["sup","deep","both"][Math.floor(r()*3)]:"no",fear:r()<level*.8},
  continence:level<.2?"yes":level<.55?"better":"no",status:seen?"seen":"lost"}
}
