const wsLine=pt=>pt&&!pt.ws&&pt.registered?t("wsPending"):pt&&pt.ws?tf("wsGot",{d:new Date(pt.ws.date+"-01T00:00:00").toLocaleDateString(LOCALES[state.lang]||"en-GB",{month:"long",year:"numeric"}),w:esc(pt.ws.place)}):t("wsNo");
