const PATH={auto:{cases:5},cert:{cases:10,m12:5,val:5},inst:{cases:20,m12:10,rate:70},co:{complete:10},minPerReport:20};
const fbOf=p=>p.fb||[];
const isValidated=p=>fbOf(p).some(m=>m.kind==="val");
