const m12Seen=p=>!!(p.visits.m12&&p.visits.m12.status==="seen");
const isDocumented=p=>{const v=p.visits.pre||{};return(v.wexner||[]).length===5&&(v.wexner||[]).every(x=>x!=null)&&f8Total(v.fiq8)!=null&&!!p.op};
const isComplete=p=>isDocumented(p)&&m12Seen(p)&&isValidated(p);
const unreadFb=p=>fbOf(p).filter(m=>m.from==="trainer"&&!m.read).length;
function journey(list){const st=stats(list);const docs=list.filter(isDocumented).length,m12=list.filter(m12Seen).length,val=list.filter(isValidated).length,rate=Math.round((st.m12Pct||0)*100);
 const lv=docs>=PATH.inst.cases&&m12>=PATH.inst.m12&&rate>=PATH.inst.rate&&val>=PATH.cert.val?3:docs>=PATH.cert.cases&&m12>=PATH.cert.m12&&val>=PATH.cert.val?2:docs>=PATH.auto.cases?1:0;
 const crit=lv===0?[["crit_cases",docs,PATH.auto.cases]]:lv===1?[["crit_cases",docs,PATH.cert.cases],["crit_m12",m12,PATH.cert.m12],["crit_val",val,PATH.cert.val]]:lv===2?[["crit_cases",docs,PATH.inst.cases],["crit_m12",m12,PATH.inst.m12],["crit_rate",rate,PATH.inst.rate]]:[];
 return{lv,docs,m12,val,rate,crit,complete:list.filter(isComplete).length}}
