 const nar=[tf("narOp1",{date:fmtDate(p.date),type:t("type_"+p.type),sp}),tf("narOp2",{x:assoc}),tf("narOp3",{q,c}),tf("narOp4",{s:sutS,a:abx}),tf("narOp5",{d:diffs})].map(esc).join(" ");
