function f8Dom(a){if(!f8n(a))return"";const s=fiq8Scores(a);return["life","cope","self","emb"].map(k=>`${t("f8s_"+k)} ${f2(s[k])}`).join(", ")+(s.raw!=null?`, ${t("f8Raw")} ${s.raw}/30`:"")+(a&&a.glob!=null?`, ${t("global")} ${a.glob}/10`:"")}
