const DICT=[["patient_code","Code patiente pseudonymisé"],["participant_id","AFYA Participant ID"],["country","Pays (code)"],["consult_date","Date de la consultation préopératoire (AAAA-MM-JJ)"],["surgery_date","Date de l'intervention (AAAA-MM-JJ)"],["procedure","SP, RVF ou BOTH"],["origin","Cause de l'incontinence : obst, trauma, sv, cong, iatro, other"],["origin_detail","Précision libre sur la cause"],["symptom_duration_months","Durée des symptômes en mois"],["prior_surgery","Incontinence déjà opérée : no, imm (réparation immédiate post-partum), sec (reconstruction secondaire), both"],["prior_secondary_success","Succès de la reconstruction secondaire : yes, no"],["urinary_lesion","Lésion urinaire associée : none, vvf, other"],["urinary_detail","Précision libre"],["exam_cloaca / exam_perineal_body / exam_rvf","Examen physique : yes, no ou vide"],["age","Âge (années)"],["op_sphincteroplasty","e2e (bout à bout), ovl (chevauchement)"],["op_associated","pr (puborectal), lev (lévatorplastie), vag (vaginoplastie), other, séparés par |"],["op_sphincter_quality","exc, med, poor"],["op_faecal_contamination","none, light, mod, high"],["op_suture_material / op_suture_size","Fil : Vicryl, PDS, Monocryl, Prolene, other ; calibre 0, 2-0, 3-0, 4-0"],["op_antibiotic / op_antibiotics","yes, no ; cro (ceftriaxone), mtz (métronidazole), cxm (céfuroxime), cfz (céfazoline), amx (amoxicilline), séparés par |"],["parity","Parité"],["difficulties","Codes séparés par |"],["complications","type:grade:date séparés par |"],["flag_discuss","1 si cas à discuter"],["{tp}_status","seen, lost ou vide ; tp = pre, d30, m6, m12, late"],["late_date / late_months_since_surgery","Suivi tardif : date (AAAA-MM-JJ) et délai en mois depuis l'intervention"],["{tp}_wexner","Total Wexner 0 à 20"],["{tp}_fiq8_total","AFYA-FIQ8, total équivalent FIQL 4 à 16 (haut = meilleure qualité de vie) ; vide si un domaine n'est pas calculable"],["{tp}_fiq8_score100","(total / 4 - 1) / 3 x 100, 0 à 100"],["{tp}_fiq8_raw","Brut AFYA 0 à 30 (somme des 10 réponses, haut = retentissement important) ; vide si une réponse manque"],["{tp}_fiq8_lifestyle / coping / selfperception / embarrassment","Domaines 1 à 4 = 4 - moyenne des réponses : Q1, Q2, A, B (au moins 2) ; Q3 à Q5 (au moins 2) ; Q6 (obligatoire) ; Q7, Q8 (au moins 1). NA = manquant"],["{tp}_fiq8_prayer / intimate","Réponses brutes A et B (0 à 3 ou na)"],["{tp}_fiq8_global","Question globale 0 à 10, hors score"],["{tp}_sex_active / fear","1, 0 ou vide"],["{tp}_dyspareunia","no, sup (superficielle), deep (profonde), both, ou vide"],["{tp}_continence","yes, better, no (suivis uniquement)"]];
function buildCSV(list){const head=["patient_code","participant_id","country","consult_date","surgery_date","procedure","origin","origin_detail","symptom_duration_months","prior_surgery","prior_secondary_success","urinary_lesion","urinary_detail","exam_cloaca","exam_perineal_body","exam_rvf","age","parity","op_sphincteroplasty","op_associated","op_sphincter_quality","op_faecal_contamination","op_suture_material","op_suture_size","op_antibiotic","op_antibiotics","difficulties","complications","flag_discuss"];
 const VC=["status","wexner","fiq8_total","fiq8_score100","fiq8_raw","fiq8_lifestyle","fiq8_coping","fiq8_selfperception","fiq8_embarrassment","fiq8_prayer","fiq8_intimate","fiq8_global","sex_active","dyspareunia","fear","continence"];
 TPS.forEach(tp=>{const c=tp==="late"?["status","date","months_since_surgery",...VC.slice(1)]:VC;c.forEach(x=>head.push(`${tp}_${x}`))});
 const b=v=>v==null?"":v?1:0;const dyCode=d=>d==null?"":d===true?"yes":d===false?"no":d;const n=v=>v==null?"":(Math.round(v*100)/100);const o=x=>x==null?"":x;
 const rows=list.map(p=>{const part=PARTS.find(x=>x.id===p.pid);const r=[p.code,p.pid,part.country,p.consultDate||"",p.date,p.type,p.origin,p.causeNote||"",p.durMonths??"",p.prior||"",(p.prior==="sec"||p.prior==="both")?(p.priorOk||""):"",p.uro||"",p.uroNote||"",p.cloaca||"",p.pbody||"",p.rvfEx||"",p.age,p.parity,...(o=>[o.spType||"",(o.assoc||[]).join("|"),o.quality||"",o.contam||"",(o.suture||{}).mat||"",(o.suture||{}).size||"",o.abx||"",(o.abxList||[]).join("|")])(p.op||{}),p.diffs.join("|"),p.comps.map(c=>`${c.type}:${c.grade}:${c.date}`).join("|"),p.flag?1:0];
  TPS.forEach(tp=>{const v=p.visits[tp];const nCol=tp==="late"?VC.length+2:VC.length;if(!v){r.push(...Array(nCol).fill(""));return}
   const lost=v.status==="lost";const f=fiq8Scores(v.fiq8);const a=v.fiq8||{};const L_=x=>lost?"":x;
   r.push(v.status);if(tp==="late")r.push(v.date||"",monthsBetween(p.date,v.date)??"");
   r.push(L_(n(wxTotal(v.wexner))),L_(n(f.total)),L_(n(f.score100==null?null:Math.round(f.score100*10)/10)),L_(o(f.raw)),L_(n(f.life)),L_(n(f.cope)),L_(n(f.self)),L_(n(f.emb)),L_(o(a.fA)),L_(o(a.fB)),L_(o(a.glob)),L_(b(v.sex&&v.sex.active)),L_(dyCode(v.sex&&v.sex.dysp)),L_(b(v.sex&&v.sex.fear)),v.continence||"")});
  return r.map(x=>{x=String(x);return/[",;\n]/.test(x)?'"'+x.replace(/"/g,'""')+'"':x}).join(",")});
 return[head.join(","),...rows].join("\n")}
